"""Extra verification: DPLL SAT solver + brute-force DS on larger instances."""
import itertools, random, time
from reduce import reduce


def dpll(clauses, assignment):
    # clauses: list of frozensets of literals
    while True:
        # unit propagation
        unit = None
        for c in clauses:
            if len(c) == 0:
                return False
            if len(c) == 1:
                unit = next(iter(c))
                break
        if unit is None:
            break
        lit = unit
        var = abs(lit)
        val = lit > 0
        assignment[var] = val
        new = []
        for c in clauses:
            if lit in c:
                continue
            if -lit in c:
                nc = c - {-lit}
                if len(nc) == 0:
                    return False
                new.append(nc)
            else:
                new.append(c)
        clauses = new
    if not clauses:
        return True
    # pure literal
    lits = set()
    for c in clauses:
        lits |= c
    for lit in lits:
        if -lit not in lits:
            assignment[abs(lit)] = lit > 0
            return dpll([c for c in clauses if lit not in c], assignment)
    # branch
    lit = next(iter(clauses[0]))
    for choice in (lit, -lit):
        a2 = dict(assignment)
        a2[abs(choice)] = choice > 0
        new = []
        ok = True
        for c in clauses:
            if choice in c:
                continue
            if -choice in c:
                nc = c - {-choice}
                if len(nc) == 0:
                    ok = False
                    break
                new.append(nc)
            else:
                new.append(c)
        if ok and dpll(new, a2):
            return True
    return False


def solve_sat(instance):
    clauses = [frozenset(c) for c in instance["clauses"]]
    return dpll(clauses, {})


def solve_ds(instance):
    n, edges, k = instance["n"], instance["edges"], instance["k"]
    if k < 0: return False
    if n == 0 or k >= n: return True
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v); adj[v].add(u)
    for size in range(0, k + 1):
        for sub in itertools.combinations(range(n), size):
            ch = set(sub)
            if all(v in ch or (adj[v] & ch) for v in range(n)):
                return True
    return False


rng = random.Random(999)
run = passed = 0
for _ in range(400):
    n = rng.randint(0, 9)
    p = rng.choice([0.1, 0.25, 0.4, 0.6, 0.85, 1.0])
    edges = [[u, v] for u in range(n) for v in range(u+1, n) if rng.random() < p]
    k = rng.randint(-1, n + 1)
    inst = {"n": n, "edges": edges, "k": k}
    red = reduce(inst)
    a, b = solve_ds(inst), solve_sat(red)
    run += 1
    assert a == b, (inst, red, a, b)
    passed += 1

print(f"extra tests_run={run} tests_passed={passed}")

# scaling check
for n in [50, 100, 200, 400]:
    edges = [[u, v] for u in range(n) for v in range(u+1, n) if (u*v) % 7 == 0]
    inst = {"n": n, "edges": edges, "k": n // 3}
    t = time.time()
    red = reduce(inst)
    dt = time.time() - t
    print(f"n={n} edges={len(edges)} k={inst['k']} -> num_vars={red['num_vars']} clauses={len(red['clauses'])} time={dt:.4f}s")
EOF
